using System;using System.IO;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;
namespace IdleIntelligence.Tests
{
 public sealed class NarrativeRuntimeTests
 {
  [Test]public void GuidedIntroSkipAndReloadAreActualState(){var s=Game.New(1000000,guided:true);s=NarrativeBridge.Action(s,"name","AURA");Assert.That(s.Story.open,Is.EqualTo("prologue-welcome"));for(int i=0;i<5;i++)s=NarrativeBridge.Action(s,"continue");Assert.That(s.Story.target,Is.EqualTo("tap"));s=NarrativeBridge.Sync(s,Game.Tap(s,s.SavedAt));s=NarrativeBridge.Sync(s,Game.Buy(s,"calculator"));Assert.That(s.Story.target,Is.EqualTo("training"));Assert.That(Game.IntroQuality(s),Is.True);s=NarrativeBridge.Action(s,"skip-tutorial");Assert.That(Game.IntroQuality(s),Is.False);s=NarrativeBridge.Action(s,"resume");Assert.That(Game.IntroQuality(s),Is.True);var before=s;s=NarrativeBridge.Sync(s,Game.Train(s,"quality"));Assert.That(s.Journal.Has("training-start"),Is.True);Assert.That(before.Journal.Has("training-start"),Is.False);s=Game.Advance(s,s.SavedAt+30000);Assert.That(s.Training,Is.Null);Assert.That(NarrativeBridge.Facts(s).trainingEvent,Is.True);var codec=new UnitySaveCodec();var reload=codec.Decode(codec.Encode(StateData.From(s)),AtomicSaveStore.Version).ToState();Assert.That(reload.Story.target,Is.EqualTo(s.Story.target));Assert.That(reload.Journal.Has("training-start"),Is.True);Game.Validate(reload);}
  [Test]public void JournalIsBoundedAndNoHistoricalEventsAreInvented(){var s=Game.New(1000000);LocalJournal.Record(s,"training-start");for(int i=0;i<500;i++)LocalJournal.Record(s,"research-start",i.ToString());Assert.That(s.Journal.recent.Length,Is.EqualTo(500));Assert.That(s.Journal.Has("training-start"),Is.False);Assert.That(s.Journal.dropped,Is.EqualTo(1));LocalJournal.Validate(s.Journal);var dto=StateData.From(s);dto.story=null;dto.journal=null;var migrated=dto.ToState();Assert.That(migrated.Journal.recent,Is.Empty);Assert.That(migrated.Journal.historicalAvailable,Is.False);Assert.That(migrated.Story.legacyIntro,Is.True);}
 }
}
